//Obtenemos el control HTML
var html = theRoot.dataView().control( "VIS_HTM" );

//Leemos el código fuente del objeto HTML
var codigo = html.sourceCode();

//Qué acción disparó el click: "venta", "refrescar-datos", "refrescar-articulos", "verificar-carrito" o "configurar"
var mAccion = codigo.match(/id="accionHtml"[^>]*>([^<]*)<\/div>/);
var accion = (mAccion && mAccion[1]) ? mAccion[1] : "venta";
theRoot.setVar("ACC_HTML", accion);

//Venta: sacamos el JSON del DIV dataJson
if (accion == "venta") {
	var mJson = codigo.match(/id="dataJson">([\s\S]*?)<\/div>/);
	theRoot.setVar("CON_HTML", mJson ? mJson[1] : "");
}

//Verificar carrito: sacamos {token, articulos:[{id,cantidad,precio}]} del DIV carritoVerificar
if (accion == "verificar-carrito") {
	var mCar = codigo.match(/id="carritoVerificar"[^>]*>([^<]*)<\/div>/);
	theRoot.setVar("CAR_HTML", mCar ? mCar[1] : "");
}

//Obtenemos el control del visor HTML
var html = theRoot.dataView().control( "VIS_HTM" ); 

//Le indicamos que seremos nosotros quienes controlaremos las pulsaciones de los links
html.setLinkDelegationPolicy( VCWebView.DelegateAllLinks );
